# Confirmatory corpus 3: 30 public incidents not used by v1/v2/holdout/confirm2.
#
# Each incident contributes five stored cases (literal x2, paraphrase x2,
# semantic x1). Evaluation queries are the sibling query for each layer:
# literal is identical; paraphrase and semantic deliberately use a different
# wording from the stored case query, so query-field evidence is testable.
# Facts are taken from the public summaries listed below; no incident or log is
# invented. The corpus is built before any confirm3 A/B result is produced.
param(
    [string]$MemDir = (Join-Path $PSScriptRoot "confirm3-mem"),
    [string]$Csv = (Join-Path $PSScriptRoot "confirm3-cases.csv"),
    [string]$Binary = (Join-Path $PSScriptRoot "..\rs\target\release\scx.exe"),
    [switch]$Force
)

$ErrorActionPreference = "Stop"

function Write-Utf8([string]$Path, [string]$Text) {
    [IO.File]::WriteAllText($Path, $Text, (New-Object Text.UTF8Encoding $false))
}
function CsvField([string]$Value) { return '"' + $Value.Replace('"', '""') + '"' }

if (-not (Test-Path -LiteralPath $Binary)) { throw "missing release binary: $Binary" }
if (-not (Test-Path -LiteralPath $MemDir)) { New-Item -ItemType Directory -Force -Path $MemDir | Out-Null }
$existing = @(Get-ChildItem -LiteralPath $MemDir -Force -ErrorAction SilentlyContinue)
if ($existing.Count -gt 0) {
    if (-not $Force) { throw "MemDir is not empty: $MemDir (use -Force to clear workspace-local dir)" }
    $wsRoot = (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot "..")).Path
    $memAbs = (Resolve-Path -LiteralPath $MemDir).Path
    if (-not $memAbs.StartsWith($wsRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw "refusing to clear non-workspace dir: $memAbs"
    }
    Remove-Item -LiteralPath $memAbs -Recurse -Force
    New-Item -ItemType Directory -Force -Path $memAbs | Out-Null
}

# sym/key/pa/pc/se are stored case queries; key/pb/pd/sf are evaluation
# queries. The target for pb/pd/sf is the sibling case, not a duplicate case.
$incidents = @(
    @{ id="cf82515"; src="https://web.archive.org/web/20211006135542/https://blog.cloudflare.com/todays-outage-post-mortem-82515/"; sym="cloudflare edge routers crash router rule"; key="bad router rule console command edge fleet"; pa="a bad configuration rule caused every edge router to crash and took cloudflare down"; pb="the edge router fleet collapsed after a router rule was pushed"; pc="a router rule deployed to the edge fleet crashed every router and caused a global cloudflare outage"; pd="pushing a bad router rule took down all cloudflare edge routers"; se="Cloudflare 推送错误路由规则导致全部边缘路由器崩溃，全球服务中断"; sf="一条坏路由规则下发后边缘路由器集体崩溃，Cloudflare 全球挂掉"; rc="错误路由规则被下发到边缘路由器，导致路由器全部崩溃并拖垮 Cloudflare 全球服务"; fix="回滚错误路由规则并恢复边缘路由" },
